public sealed record Stock(string Sku, int Available);

// A token bucket shared by all calls to one dependency
public sealed class RetryBudget
{
    private readonly Lock _gate = new();
    private double _tokens = 10;

    public void OnRequest() { lock (_gate) _tokens = Math.Min(10, _tokens + 0.1); }

    public bool TrySpend()
    {
        lock (_gate)
        {
            if (_tokens < 1) return false;
            _tokens--;
            return true;
        }
    }
}
